import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CT6jiXWi.js";const m=JSON.parse('{"title":"How cds-data-pipeline + cds-data-federation Compare","description":"","frontmatter":{},"headers":[],"relativePath":"federation/reference/comparison.md","filePath":"federation/reference/comparison.md","lastUpdated":1783589060000}'),n={name:"federation/reference/comparison.md"};function i(s,e,d,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="how-cds-data-pipeline-cds-data-federation-compare" tabindex="-1">How cds-data-pipeline + cds-data-federation Compare <a class="header-anchor" href="#how-cds-data-pipeline-cds-data-federation-compare" aria-label="Permalink to &quot;How cds-data-pipeline + cds-data-federation Compare&quot;">​</a></h1><p>This document positions the two packages (<code>cds-data-pipeline</code>, the engine; <code>cds-data-federation</code>, the annotation plugin) against other approaches for integrating remote services into a SAP CAP application. The space is active — SAP samples, community plugins, blog posts, database features, and enterprise platforms all tackle pieces of the same problem. The goal here is to make the trade-offs visible so you can pick the right tool for your scenario.</p><h2 id="scope-application-level-integration" tabindex="-1">Scope: application-level integration <a class="header-anchor" href="#scope-application-level-integration" aria-label="Permalink to &quot;Scope: application-level integration&quot;">​</a></h2><p>The plugin&#39;s focus is <strong>application-level integration</strong> — the CAP service is the owner of the integration contract. Consumption views, field renames, cross-service <code>$expand</code> resolution, scheduled sync, and hooks all live inside the CAP app, as part of the application&#39;s own codebase and deployment.</p><p>This is a deliberate contrast to <strong>DB-layer</strong> approaches (HANA synonyms, Smart Data Access) where integration happens underneath CAP at the database level, and to <strong>platform-layer</strong> approaches (Datasphere, generic CDC/ETL) where integration happens outside the CAP app in a data-integration platform. Those options are included in the matrices below for orientation, but they solve different problems at different architectural layers. Pick DB-layer tools when you want joins to disappear into the database; pick platform tools when data-warehouse-scale volumes or enterprise governance are the driver; pick this plugin when the CAP app itself is where the integration logic belongs.</p><p>The two strategies the plugin offers — <strong>delegation</strong> (live proxy) and <strong>replication</strong> (scheduled sync into the local DB) — compete with different alternatives, so the comparison is split accordingly.</p><hr><h2 id="cap-reference-samples" tabindex="-1">CAP reference samples <a class="header-anchor" href="#cap-reference-samples" aria-label="Permalink to &quot;CAP reference samples&quot;">​</a></h2><p>Throughout this document, <strong>CAP reference samples</strong> refers to the integration pattern shown in SAP&#39;s own sample applications:</p><ul><li><a href="https://github.com/capire/xtravels" target="_blank" rel="noreferrer"><strong>xtravels</strong></a> — the Service Integration reference sample. Delegation via <code>this.on(&#39;READ&#39;, Entity, req =&gt; remote.run(req.query))</code>, replication via a generic <code>@federated</code> handler in <a href="https://github.com/capire/xtravels/blob/main/srv/data-federation.js" target="_blank" rel="noreferrer"><code>srv/data-federation.js</code></a>.</li><li><a href="https://github.com/SAP-samples/cloud-cap-risk-management/tree/ext-service-s4hc-suppliers-ui" target="_blank" rel="noreferrer"><strong>Risk Management — ext-service branch</strong></a> — SAP&#39;s S/4HANA mashup sample. The <a href="https://github.com/SAP-samples/cloud-cap-risk-management/blob/ext-service-s4hc-suppliers-ui/srv/risk-service.js" target="_blank" rel="noreferrer"><code>risk-service.js</code></a> file wires five handlers that together cover every pattern the plugin packages.</li><li><a href="https://blog.kai-niklas.de/posts/9-sap-cap-remote-services-fiori-elements/" target="_blank" rel="noreferrer"><strong>Kai Niklas — CAP Remote Services + Fiori Elements</strong></a> — an end-to-end walkthrough of the same assembly for a Fiori Elements frontend.</li><li><a href="https://github.com/gregorwolf/cap-replication-demo" target="_blank" rel="noreferrer"><strong>Gregor Wolf — cap-replication-demo</strong></a> — a replication-focused demo against the S/4HANA Business Partner API (<code>API_BUSINESS_PARTNER</code>). Illustrates the full recipe for scheduled sync at the application layer: action-triggered load (<code>loadEntitiesFromS4</code>), an offset pagination loop driven by <code>$count</code>, per-entity column projection and destination routing via a <code>map.js</code> config, <code>UPSERT(entity).into(table)</code> for idempotent writes, and event-driven upsert on <code>sap.s4.beh.businesspartner.v1.BusinessPartner.Changed.v1</code> via <code>cds.connect.to(&#39;messaging&#39;)</code>. The scheduler, delta tracking, retry, and concurrency guard that <code>@federation.replicate</code> contributes are not part of the demo, which makes it a useful side-by-side reference for the moving parts the annotation covers.</li></ul><p>CAP provides all the primitives (<code>cds.connect.to</code>, <code>srv.run</code>, projection chains, <code>@cds.persistence.table</code>, <code>UPSERT</code>, <code>cds.outboxed</code>). The reference samples assemble them per entity. <code>cds-data-federation</code> packages the same assembly behind two annotations so each federated entity is one declaration, not a handler file.</p><hr><h2 id="delegation-alternatives" tabindex="-1">Delegation alternatives <a class="header-anchor" href="#delegation-alternatives" aria-label="Permalink to &quot;Delegation alternatives&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>cds-data-federation (delegate)</th><th>CAP reference samples</th><th>CAP + <a href="https://github.com/mikezaschka/cds-caching" target="_blank" rel="noreferrer">cds-caching</a></th><th><a href="https://github.com/cap-js-community/common" target="_blank" rel="noreferrer">@cap-js-community/common</a> (Replication Cache)</th><th>HANA-native (synonyms / SDA)</th></tr></thead><tbody><tr><td>Architectural layer</td><td>application</td><td>application</td><td>application</td><td>application</td><td>database</td></tr><tr><td>Zero handler code (declarative)</td><td>yes, via annotation</td><td>handler per entity</td><td>handler plus cache wrap per entity</td><td>yes, via <code>@cds.replicate</code></td><td>yes, via <code>.hdbsynonym</code> / virtual tables</td></tr><tr><td>Live forwarding of reads</td><td>yes</td><td>yes</td><td>yes (with cached reads)</td><td>no — served from SQLite snapshot within TTL</td><td>yes, as native HANA joins</td></tr><tr><td>Cross-service <code>$expand</code></td><td>yes — four expand topologies + navigation</td><td>coded per scenario</td><td>coded per scenario</td><td>no — each entity cached independently</td><td>limited to same HANA DB</td></tr><tr><td>Field / association renames</td><td>automatic from projection</td><td>CAP projection chain</td><td>CAP projection chain</td><td>no — data cached verbatim</td><td>via CDS view on top of synonym</td></tr><tr><td>Write-back (CUD)</td><td>opt-in per entity</td><td>coded per entity</td><td>not cache-applicable</td><td>not supported (read-only)</td><td>depends on target schema grants; typically read-only</td></tr><tr><td>Caching model</td><td>response-level (<code>cds-caching</code>) or entity-level (<code>cache.strategy: &#39;entity&#39;</code>, SQLite + pipeline)</td><td>none</td><td>response-level</td><td>entity-level (full dataset into per-tenant SQLite, TTL + LRU)</td><td>DB-level only</td></tr><tr><td>Non-HANA sources</td><td>yes</td><td>yes</td><td>yes</td><td>yes</td><td>SDA only (MSSQL, Oracle, Postgres, remote HANA)</td></tr></tbody></table><h3 id="note-on-hana-native-integration" tabindex="-1">Note on HANA-native integration <a class="header-anchor" href="#note-on-hana-native-integration" aria-label="Permalink to &quot;Note on HANA-native integration&quot;">​</a></h3><p>HANA synonyms (<code>.hdbsynonym</code>) and Smart Data Access are two tools in the same DB-layer kit: synonyms alias a table or view in another HANA schema (typically the same HANA instance, e.g., an S/4HANA CDS view in a paired schema), SDA provides virtual tables that federate remote HANA or non-HANA sources. In CAP projects they are often combined — an SDA virtual table in one schema, a synonym in the app&#39;s HDI container pointing at it — so the combined column reflects the typical deployment. They are a strong fit when the integration boundary should live in the database: native joins, pushdown to HANA&#39;s query engine, no CAP-level handler code. When the integration contract instead lives in the application service — consumption views, per-consumer renames, cross-service <code>$expand</code>, CUD write-back — an application-layer approach like <code>cds-data-federation</code> is the closer match.</p><h3 id="note-on-the-replication-cache" tabindex="-1">Note on the Replication Cache <a class="header-anchor" href="#note-on-the-replication-cache" aria-label="Permalink to &quot;Note on the Replication Cache&quot;">​</a></h3><p><a href="https://github.com/cap-js-community/common" target="_blank" rel="noreferrer"><code>@cap-js-community/common</code></a> loads a full entity dataset into a per-tenant SQLite file on first access and serves subsequent queries from that snapshot within a TTL. <strong><code>cds-data-federation</code></strong> offers a similar <strong><code>cache.strategy: &#39;entity&#39;</code></strong> path on <code>@federation.delegate</code> — same performance profile (one remote full read, then local CQN), but consumption-view aware (field renames, column restriction) and composable with federation cross-service features where the MVP allows. <strong><code>cache.strategy: &#39;response&#39;</code></strong> (<a href="https://github.com/mikezaschka/cds-caching" target="_blank" rel="noreferrer"><code>cds-caching</code></a>) remains the choice for identical query repetition. See <a href="./../integration/caching.html">Integration → Caching</a>.</p><hr><h2 id="replication-alternatives" tabindex="-1">Replication alternatives <a class="header-anchor" href="#replication-alternatives" aria-label="Permalink to &quot;Replication alternatives&quot;">​</a></h2><p>The application-layer column is split into two: <strong>federation plugin</strong> (<code>cds-data-federation</code>, annotation surface for <code>@federation.replicate</code>) and <strong>pipeline engine</strong> (<code>cds-data-pipeline</code>, the scheduled sync pipeline the plugin composes). Columns attribute capabilities to whichever package owns them; a user reaching for <code>@federation.replicate</code> installs both, while a user writing a programmatic pipeline against a non-federation source installs only the engine.</p><table tabindex="0"><thead><tr><th>Capability</th><th>cds-data-federation (<code>@federation.replicate</code>)</th><th>cds-data-pipeline (engine, standalone)</th><th>CAP reference samples (sync code)</th><th>SAP Business Data Cloud (Datasphere Replication Flow)</th><th>Generic CDC / ETL (Debezium, Airflow, dbt)</th></tr></thead><tbody><tr><td>Architectural layer</td><td>application</td><td>application</td><td>application</td><td>platform</td><td>platform</td></tr><tr><td>Consumption contract</td><td>CDS projection on remote + annotation</td><td>programmatic <code>addPipeline({ kind, source, target, mapping, schedule })</code></td><td>hand-assembled per entity</td><td>modeled in the platform</td><td>pipeline code</td></tr><tr><td>Zero setup code (declarative)</td><td>yes, via annotation + schedule</td><td>no — programmatic API</td><td>assembled per entity</td><td>yes, modeled in the platform</td><td>no, pipeline code</td></tr><tr><td>Scheduled full / delta sync</td><td>inherits engine via composition</td><td>yes, both modes</td><td>rolled per job</td><td>yes</td><td>yes</td></tr><tr><td>Idempotent writes (UPSERT)</td><td>inherits engine</td><td>built-in</td><td>coded per entity</td><td>yes</td><td>depends on pipeline</td></tr><tr><td>Retry + concurrency guard</td><td>inherits engine</td><td>built-in (<code>withRetry</code> + optimistic tracker update)</td><td>coded per job</td><td>platform-managed</td><td>platform-managed</td></tr><tr><td>Non-OData / REST sources</td><td>inherits engine</td><td>yes, adapter factory (OData, REST, pluggable <code>BaseAdapter</code>)</td><td>adapter code required</td><td>yes</td><td>yes (core strength)</td></tr><tr><td>Field / association renames</td><td>from consumption view (<code>localToRemote</code> / <code>remoteToLocal</code>)</td><td>via <code>PIPELINE.MAP</code> hook</td><td>projection + explicit mapping</td><td>via transformations</td><td>pipeline code</td></tr><tr><td>Caching model</td><td>response-level option (via <a href="https://github.com/mikezaschka/cds-caching" target="_blank" rel="noreferrer">cds-caching</a>)</td><td>not applicable (engine is the sync layer)</td><td>none</td><td>n/a (queries go to local tables)</td><td>n/a</td></tr><tr><td>Observability surface</td><td>same management API as engine</td><td>tracker + run entities + OData management service</td><td>none</td><td>platform-managed</td><td>platform-managed</td></tr><tr><td>Primary scale target</td><td>app-level integration</td><td>app-level integration</td><td>app-level integration</td><td>enterprise data landscape</td><td>data-warehouse / lake</td></tr></tbody></table><hr><h2 id="positioning" tabindex="-1">Positioning <a class="header-anchor" href="#positioning" aria-label="Permalink to &quot;Positioning&quot;">​</a></h2><p>The plugin targets the <strong>application layer</strong> exclusively: a CAP service that needs remote data shaped into its own model, where the integration contract is part of the application&#39;s own codebase and lifecycle. Within that scope, the goal is to lift the per-entity handler work from the Service Integration samples into a single annotation on the consumption view.</p><p>Outside that scope, other tools remain the right choice:</p><ul><li><strong>HANA synonyms / SDA</strong> — pick when the integration boundary logically belongs to the database, queries stay within HANA, and native joins and pushdown are the point.</li><li><strong>SAP Business Data Cloud (BDC)</strong> — the umbrella data platform announced Feb 2025 that now contains Datasphere, Databricks integration, Analytics Cloud, and Joule agents. Pick for a governed, enterprise-scale data fabric across SAP applications; Datasphere&#39;s Replication Flow (in the table above) is the specific feature that competes with <code>@federation.replicate</code>.</li><li><strong>SAP Cloud Integration (Integration Suite)</strong> — iPaaS. Pick when the integration itself is the deliverable — transformation logic, B2B/EDI, messaging-based A2A, routing, error handling in middleware. Also a valid <em>upstream producer</em>: CPI can expose a virtualized OData/REST endpoint that a CAP app then consumes via <code>@federation.delegate</code>, or push into a HANA Cloud table that the app reads locally. For pure scheduled replication without the transformation/messaging needs, Datasphere Replication Flow is a more direct match.</li><li><strong>SAP Graph</strong> — semantic federation API layering a unified business data model (One Domain Model, ODM) over multiple SAP systems (S/4HANA, SuccessFactors, Ariba, Concur). Pick when a harmonized, cross-system <em>read</em> API is the deliverable. Orthogonal to the plugin: if SAP Graph exposes OData for a given context, it can be a <code>@federation.delegate</code> source like any other OData service; the plugin&#39;s consumption-view + rename + cross-service <code>$expand</code> features apply unchanged. Distinct from SAP MDI (next bullet), which focuses on master data distribution lifecycle rather than unified read access.</li><li><strong>SAP Master Data Integration (MDI)</strong> — BTP service for distributing master data (business partners, products, cost centers, employees) across SAP cloud apps, built on the same ODM as SAP Graph. Pick when master data lifecycle — CRUD propagation, soft-delete, cross-system harmonization — is the problem. Architecturally similar to SAP Graph from the plugin&#39;s perspective (OData APIs on BTP), so it is a candidate <code>@federation.delegate</code> / <code>@federation.replicate</code> source. Most natural pairing is MDI-emitted change events on Event Mesh driving the (Phase 6+) event-driven sync into a local cache.</li><li><strong>Generic CDC / ETL (Debezium, Airflow, dbt)</strong> — pick when data pipelines across heterogeneous systems are the deliverable and CAP is just one consumer among many.</li></ul><p>Within the application layer, the plugin complements rather than replaces neighboring tools:</p><ul><li><a href="https://github.com/mikezaschka/cds-caching" target="_blank" rel="noreferrer"><code>cds-caching</code></a> — optional peer for <code>cache.strategy: &#39;response&#39;</code>.</li><li><strong><code>cache.strategy: &#39;entity&#39;</code></strong> — built-in SQLite entity cache via <code>cds-data-pipeline</code>; see <a href="./../integration/caching.html">Caching</a>.</li><li><a href="https://github.com/cap-js-community/common" target="_blank" rel="noreferrer"><code>@cap-js-community/common</code></a> offers entity-level caching as a standalone alternative if that specific pattern is all you need.</li><li><strong>SAP Event Mesh</strong> — not a competitor; the CloudEvents-based messaging backbone that SAP systems publish to and that CAP subscribes to via <code>cds.connect.to(&#39;messaging&#39;)</code>. When event-driven sync is added to the replicate strategy, Event Mesh — or any CAP-supported broker (Redis PubSub, Kafka, local in-process) — will be the transport. Complementary to both delegate and replicate strategies.</li></ul><hr><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>CAP Service Integration guide</td><td><a href="https://cap.cloud.sap/docs/guides/integration/calesi" target="_blank" rel="noreferrer">https://cap.cloud.sap/docs/guides/integration/calesi</a></td></tr><tr><td>CAP Data Federation guide</td><td><a href="https://cap.cloud.sap/docs/guides/integration/data-federation" target="_blank" rel="noreferrer">https://cap.cloud.sap/docs/guides/integration/data-federation</a></td></tr><tr><td>xtravels (Service Integration reference sample)</td><td><a href="https://github.com/capire/xtravels" target="_blank" rel="noreferrer">https://github.com/capire/xtravels</a></td></tr><tr><td>xflights (provider sample)</td><td><a href="https://github.com/capire/xflights" target="_blank" rel="noreferrer">https://github.com/capire/xflights</a></td></tr><tr><td>Risk Management ext-service branch</td><td><a href="https://github.com/SAP-samples/cloud-cap-risk-management/tree/ext-service-s4hc-suppliers-ui" target="_blank" rel="noreferrer">https://github.com/SAP-samples/cloud-cap-risk-management/tree/ext-service-s4hc-suppliers-ui</a></td></tr><tr><td>Kai Niklas — CAP Remote Services + Fiori Elements</td><td><a href="https://blog.kai-niklas.de/posts/9-sap-cap-remote-services-fiori-elements/" target="_blank" rel="noreferrer">https://blog.kai-niklas.de/posts/9-sap-cap-remote-services-fiori-elements/</a></td></tr><tr><td>Gregor Wolf — cap-replication-demo</td><td><a href="https://github.com/gregorwolf/cap-replication-demo" target="_blank" rel="noreferrer">https://github.com/gregorwolf/cap-replication-demo</a></td></tr><tr><td>@cap-js-community/common (Replication Cache)</td><td><a href="https://github.com/cap-js-community/common" target="_blank" rel="noreferrer">https://github.com/cap-js-community/common</a></td></tr><tr><td>cds-caching</td><td><a href="https://github.com/mikezaschka/cds-caching" target="_blank" rel="noreferrer">https://github.com/mikezaschka/cds-caching</a></td></tr><tr><td>HANA Smart Data Access</td><td><a href="https://help.sap.com/docs/SAP_HANA_PLATFORM/6b94445c94ae495c83a19646e7c3fd56/6ce5a8dc7c0f44e28f12ff09db93b45c.html" target="_blank" rel="noreferrer">https://help.sap.com/docs/SAP_HANA_PLATFORM/6b94445c94ae495c83a19646e7c3fd56/6ce5a8dc7c0f44e28f12ff09db93b45c.html</a></td></tr><tr><td>HANA synonyms in CAP (Using Databases / Native HANA Features)</td><td><a href="https://cap.cloud.sap/docs/advanced/hana#native-hana-features" target="_blank" rel="noreferrer">https://cap.cloud.sap/docs/advanced/hana#native-hana-features</a></td></tr><tr><td>SAP Datasphere Replication Flow</td><td><a href="https://help.sap.com/docs/SAP_DATASPHERE" target="_blank" rel="noreferrer">https://help.sap.com/docs/SAP_DATASPHERE</a></td></tr><tr><td>SAP Cloud Integration (Integration Suite)</td><td><a href="https://help.sap.com/docs/integration-suite" target="_blank" rel="noreferrer">https://help.sap.com/docs/integration-suite</a></td></tr><tr><td>SAP Business Data Cloud</td><td><a href="https://www.sap.com/products/data-cloud.html" target="_blank" rel="noreferrer">https://www.sap.com/products/data-cloud.html</a></td></tr><tr><td>SAP Event Mesh</td><td><a href="https://help.sap.com/docs/SAP_EM" target="_blank" rel="noreferrer">https://help.sap.com/docs/SAP_EM</a></td></tr><tr><td>SAP Graph</td><td><a href="https://help.sap.com/docs/SAP_GRAPH" target="_blank" rel="noreferrer">https://help.sap.com/docs/SAP_GRAPH</a></td></tr><tr><td>SAP Master Data Integration</td><td><a href="https://help.sap.com/docs/SAP_MASTER_DATA_INTEGRATION" target="_blank" rel="noreferrer">https://help.sap.com/docs/SAP_MASTER_DATA_INTEGRATION</a></td></tr></tbody></table>',32)])])}const g=t(n,[["render",i]]);export{m as __pageData,g as default};
